using Avalonia;
using Avalonia.Controls;
using Avalonia.Headless;
using Avalonia.Headless.XUnit;
using Avalonia.Input;
using Avalonia.Threading;
using ProDesigner.Workbench;
using Xunit;

namespace ProDesigner.Tests;
public class PointerTests
{
    private static (DesignerWorkbench Workbench, Window Window) Create()
    {
        var workbench = new DesignerWorkbench();
        workbench.OpenDocument("Pointer.axaml", "<UserControl xmlns=\"https://github.com/avaloniaui\" xmlns:x=\"http://schemas.microsoft.com/winfx/2006/xaml\"><Canvas><Border x:Name=\"Card\" Canvas.Left=\"80\" Canvas.Top=\"80\" Width=\"160\" Height=\"100\" Background=\"Purple\"/></Canvas></UserControl>");
        workbench.Surface.Profiles = [new("Test", 960,620)]; workbench.Surface.Rebuild(); workbench.Surface.SetZoom(1);
        var window = new Window { Width = 1600, Height = 1000, Content = workbench }; window.Show();
        Dispatcher.UIThread.RunJobs(); workbench.Surface.SetZoom(1); window.UpdateLayout();
        return (workbench, window);
    }
    [AvaloniaFact]
    public void PointerDragCommitsOneUndoableSourceTransaction()
    {
        var (workbench, window) = Create(); using var disposable = workbench;
        var source = workbench.Session.Source;
        var rect = workbench.Surface.GetElementBounds("Card")!.Value;
        var start = new Point(rect.X+20,rect.Y+20); var end = start + new Vector(24,16);
        window.MouseDown(start, MouseButton.Left); window.MouseMove(end, RawInputModifiers.LeftMouseButton | RawInputModifiers.Alt); window.UpdateLayout(); window.MouseUp(end,MouseButton.Left,RawInputModifiers.Alt);
        Assert.Equal("104", workbench.Session.Primary!.Get("Canvas.Left")); Assert.Equal("96", workbench.Session.Primary.Get("Canvas.Top"));
        workbench.Execute("undo"); Assert.Equal(source, workbench.Session.Source); window.Close();
    }
    [AvaloniaFact]
    public void NorthWestHandleChangesSizeAndPosition()
    {
        var (workbench, window) = Create(); using var disposable = workbench; workbench.SelectByName("Card");
        var rect = workbench.Surface.GetElementBounds("Card")!.Value;
        var start = new Point(rect.X,rect.Y); var end = start + new Vector(16,16);
        window.MouseDown(start, MouseButton.Left); window.MouseMove(end,RawInputModifiers.LeftMouseButton|RawInputModifiers.Alt); window.UpdateLayout(); window.MouseUp(end,MouseButton.Left,RawInputModifiers.Alt);
        Assert.Equal("144",workbench.Session.Primary!.Get("Width")); Assert.Equal("84",workbench.Session.Primary.Get("Height"));
        Assert.Equal("96",workbench.Session.Primary.Get("Canvas.Left")); Assert.Equal("96",workbench.Session.Primary.Get("Canvas.Top")); window.Close();
    }
    [AvaloniaFact]
    public void EscapeCancelsAnInFlightGestureWithoutChangingSource()
    {
        var (workbench, window) = Create(); using var disposable = workbench;
        var source = workbench.Session.Source; var before = workbench.Surface.GetElementBounds("Card")!.Value;
        var start = new Point(before.X+20,before.Y+20); var end = start + new Vector(70,20);
        window.MouseDown(start,MouseButton.Left); window.MouseMove(end,RawInputModifiers.LeftMouseButton); workbench.Surface.CancelGesture(); window.UpdateLayout(); window.MouseUp(end,MouseButton.Left);
        Assert.Equal(source,workbench.Session.Source); Assert.Equal(before,workbench.Surface.GetElementBounds("Card")!.Value); window.Close();
    }
}

using ProDesigner.Design;
using Xunit;

namespace ProDesigner.Tests;
public class ResizeTests
{
    [Theory]
    [InlineData(ResizeEdges.Left, 120, 100, 80, 80)]
    [InlineData(ResizeEdges.Right, 100, 100, 120, 80)]
    [InlineData(ResizeEdges.Top, 100, 120, 100, 60)]
    [InlineData(ResizeEdges.Bottom, 100, 100, 100, 100)]
    [InlineData(ResizeEdges.Left | ResizeEdges.Top, 120, 120, 80, 60)]
    [InlineData(ResizeEdges.Right | ResizeEdges.Bottom, 100, 100, 120, 100)]
    public void ResizingKeepsTheOppositeEdgesFixed(ResizeEdges edges, double x, double y, double w, double h)
    {
        Assert.Equal(new DesignRect(x, y, w, h), ResizeGeometry.Resize(new(100,100,100,80), edges, 20,20,false));
    }
    [Fact] public void AllEightHandlesAreInteractive() => Assert.Equal(8, ResizeGeometry.Handles(new(0,0,100,100)).Select(h => ResizeGeometry.HitTest(new(0,0,100,100), h.X,h.Y)).Distinct().Count());
    [Fact] public void ResizingCannotInvertTheBox() => Assert.Equal(8, ResizeGeometry.Resize(new(0,0,100,100), ResizeEdges.Left, 500,0,false).Width);
    [Fact] public void ShiftResizePreservesAspectRatio()
    {
        var resized = ResizeGeometry.Resize(new(0,0,100,50), ResizeEdges.Right|ResizeEdges.Bottom, 40,0,false,true);
        Assert.Equal(2, resized.Width/resized.Height);
    }
}

using Avalonia.Controls;
using Avalonia.Headless.XUnit;
using ProDesigner.Core;
using ProDesigner.Runtime;
using ProDesigner.TestFixture;
using ProDesigner.Workspaces;
using Xunit;

namespace ProDesigner.Tests;
public class RuntimeTests
{
    [AvaloniaFact]
    public void RuntimePreviewUsesRealAvaloniaXamlAndCustomProjectControls()
    {
        const string source = "<UserControl xmlns=\"https://github.com/avaloniaui\" xmlns:x=\"http://schemas.microsoft.com/winfx/2006/xaml\" xmlns:local=\"using:ProDesigner.TestFixture\" x:Class=\"ProDesigner.TestFixture.PreviewView\"><local:ProjectCard Caption=\"Resolved from project metadata\" Width=\"123\" /></UserControl>";
        using var preview = new RuntimePreviewEngine().Load(new(source, Trusted: true), typeof(PreviewView).Assembly.Location);
        Assert.Equal("ProDesigner.TestFixture.PreviewView", preview.Root.GetType().FullName);
        var child = Assert.IsAssignableFrom<Control>(((UserControl)preview.Root).Content);
        Assert.Equal("ProDesigner.TestFixture.ProjectCard", child.GetType().FullName); Assert.Equal(123,child.Width);
        Assert.Equal("Resolved from project metadata",child.GetType().GetProperty("Caption")!.GetValue(child));
    }
    [Fact] public void UntrustedRuntimeNeverLoadsCode() => Assert.Throws<UnauthorizedAccessException>(() => new RuntimePreviewEngine().Load(new("<UserControl/>")));
    [Fact] public async Task UntrustedBuildNeverStartsAProcess() => await Assert.ThrowsAsync<UnauthorizedAccessException>(() => new DotNetProjectBuilder().BuildAsync(new("missing.csproj", false), TestContext.Current.CancellationToken));
}
